export type IntegrationIconName =
  (typeof integrationIconCatalog)[number]["name"];

export const integrationIconNameByIntegration: Readonly<
  Record<string, IntegrationIconName | undefined>
> = Object.fromEntries(
  integrationIconCatalog.flatMap(
    (icon: {
      name: IntegrationIconName;
      integrationNames: readonly string[];
    }) =>
      icon.integrationNames.map((name): [string, IntegrationIconName] => [
        name,
        icon.name,
      ]),
  ),
);

